$string['panel_bychannel_best'] = 'Entre os canais com pelo menos {$a->fair} famílias, o que mais matricula é {$a->best} ({$a->bestfrac}) e o que menos, {$a->worst} ({$a->worstfrac}).';
$string['panel_bychannel_foot'] = 'Como se conta: a origem é o primeiro contacto medido e não muda depois. Uma jornada, uma chamada ou o cartaz da porta são portas, nunca a origem, e um anúncio só conta se a família era nova. O perfil do Google, por utm_medium=ficha; a publicidade, por um meio pago (cpc, paid, ads, campaign); os e-mails e mensagens da escola, por email, newsletter ou sms; os impressos, por qr ou impreso; as redes, por social ou por vir de uma rede; o site da escola, pelo domínio do seu e-mail ou pelos seus formulários. Sem nada medido, conta o que a família disse em «Como nos conheceram?»; se também não o disse, vai para «Sem medição» e não se atribui a ninguém. Nenhum canal leva mais do que o medido: um anúncio visto sem clicar não deixa rasto e pode acabar numa pesquisa ou numa visita direta ao site, e quem deixa o contacto num anúncio pode ter conhecido a escola antes. Quem são sai das listas da escola, do que dizem as famílias e a equipa, e da lista de antigos alunos.';
