$string['qs_letters_def'] = 'As cartas dos atos que saíram por correio eletrónico nesta campanha, sem as de amostra; as que voltaram não contam nas horas nem nos dias. Uma carta está aberta quando a família abre a sua ligação e a vê um momento: os programas que verificam as ligações não contam. «Abertas em dois dias» olha só para as que já estão fora há dois dias, para que as recentes não pareçam piores. «Metade reagiu em» é o tempo em que metade das famílias que a abriram ou responderam numa semana o fez, com cinco ou mais. A hora e o dia são os do centro.';
